'use strict';
window.NeoNotifications=(()=>{
 let owner='',admin=false,orders=[],materials=[],busy=false,last=0,timer=null,previous={sales:0,group:0,direct:0,human:0,library:0};
 const toastTimers=new Map();
 const storage=(name,session=false)=>`${name}:${owner}${session?':session':''}`;
 const get=(name,session=false)=>{try{return (session?sessionStorage:localStorage).getItem(storage(name,session))||''}catch{return ''}};
 const set=(name,value,session=false)=>{try{(session?sessionStorage:localStorage).setItem(storage(name,session),String(value))}catch{}};
 const enabled=()=>get('neo-notifications-enabled')!=='0';
 const messages=()=>window.NeoCommunityAlerts?.snapshot?.()||{group:0,direct:0,threads:[]};
 const seenSales=()=>{try{return localStorage.getItem('neo-shop-orders-seen:'+owner)||''}catch{return ''}};
 const salesCount=()=>{const seen=seenSales();return admin?orders.filter(order=>!seen||String(order.created_at)>seen).length:0};
 const humanCount=()=>admin?(messages().threads||[]).filter(thread=>Number(thread.unread)>0&&(!thread.agent_mode||thread.agent_mode==='manual')).reduce((sum,thread)=>sum+Number(thread.unread||0),0):0;
 const libraryLatest=()=>materials.reduce((latest,item)=>String(item.created_at||item.updated_at||'')>latest?String(item.created_at||item.updated_at||''):latest,'');
 const libraryCount=()=>{const seen=get('neo-library-seen');return seen?materials.filter(item=>String(item.created_at||item.updated_at||'')>seen).length:0};

 function shopBadge(){const button=document.querySelector('#nav button[data-go="loja"]');if(!button)return;button.classList.add('nav-shop');let badge=button.querySelector('.nav-shop-count');if(!badge){badge=document.createElement('b');badge.className='nav-shop-count';button.append(badge)}const count=salesCount();badge.hidden=!count;badge.textContent=count>99?'99+':String(count);button.setAttribute('aria-label',count?`Loja: ${count} pedido${count===1?' novo':'s novos'}`:'Loja')}
 function stack(){let root=document.querySelector('[data-notification-toasts]');if(!root){root=document.createElement('div');root.className='notification-toast-stack';root.dataset.notificationToasts='';root.setAttribute('aria-live','polite');root.setAttribute('aria-atomic','false');document.body.append(root)}return root}
 function dismiss(kind){const node=document.querySelector(`[data-notification-toast="${kind}"]`);if(!node)return;clearTimeout(toastTimers.get(kind));toastTimers.delete(kind);node.classList.add('is-leaving');setTimeout(()=>node.remove(),220)}
 function show(kind,title,text,count=0){if(!enabled()||!owner||!count)return;const root=stack();let node=root.querySelector(`[data-notification-toast="${kind}"]`);if(!node){node=document.createElement('article');node.className=`notification-toast notification-toast-${kind}`;node.dataset.notificationToast=kind;node.innerHTML='<button type="button" class="notification-toast-main" data-notification-action><span class="notification-toast-icon" aria-hidden="true"></span><span class="notification-toast-copy"><strong></strong><small></small></span><b></b></button><button type="button" class="notification-toast-close" data-notification-dismiss aria-label="Dispensar">×</button><span class="notification-toast-progress" aria-hidden="true"></span>';root.prepend(node)}node.querySelector('strong').textContent=title;node.querySelector('small').textContent=text;node.querySelector('b').textContent=count>99?'99+':String(count);node.querySelector('.notification-toast-icon').textContent=kind==='sales'?'$':kind==='library'?'▤':kind==='human'?'!':kind==='direct'?'✉':'●';node.classList.remove('is-leaving');void node.offsetWidth;node.classList.add('is-visible');clearTimeout(toastTimers.get(kind));toastTimers.set(kind,setTimeout(()=>dismiss(kind),6500))}
 function announced(kind,signature){if(!signature)return true;const key='neo-notification-announced-'+kind;if(get(key,true)===signature)return true;set(key,signature,true);return false}
 function notify(changed={}){const snapshot=messages(),sales=salesCount(),human=humanCount(),direct=admin?human:Math.max(0,Number(snapshot.direct)||0),group=Math.max(0,Number(snapshot.group)||0),library=libraryCount();shopBadge();if(sales&&(changed.sales||sales>previous.sales)&&!announced('sales',orders[0]?.id||orders[0]?.created_at||String(sales)))show('sales',sales===1?'Nova venda':`${sales} novas vendas`,'Toque para abrir os pedidos da loja.',sales);if(group&&(changed.group||group>previous.group)&&!announced('group',String(group)))show('group',group===1?'Novidade na comunidade':`${group} novidades na comunidade`,'Toque para abrir o grupo.',group);if(direct&&(changed.direct||direct>previous.direct)){const kind=admin?'human':'direct';if(!announced(kind,String(direct)))show(kind,admin?'Atendimento solicitado':direct===1?'Nova mensagem':'Novas mensagens',admin?'Há uma conversa aguardando sua resposta.':'Toque para abrir suas conversas.',direct)}if(library&&(changed.library||library>previous.library)&&!announced('library',libraryLatest()))show('library',library===1?'Novo material na biblioteca':`${library} novos materiais`,'Toque para abrir a biblioteca.',library);previous={sales,group,direct,human,library}}

 async function refresh(force=false){shopBadge();if(!owner||busy||(!force&&Date.now()-last<30000))return;busy=true;try{const tasks=[window.NeoCloud?.library?.('read')];if(admin)tasks.push(window.NeoCloud?.shop?.('manage_orders'));const result=await Promise.allSettled(tasks);if(result[0]?.status==='fulfilled')materials=Array.isArray(result[0].value?.materials)?result[0].value.materials:[];if(admin&&result[1]?.status==='fulfilled'&&Array.isArray(result[1].value))orders=result[1].value;const latest=libraryLatest();if(latest&&!get('neo-library-seen'))set('neo-library-seen',latest);last=Date.now();notify()}catch{}finally{busy=false}}
 function session(user,isAdmin=false){const next=user?.id||'';admin=!!isAdmin;if(next!==owner){owner=next;orders=[];materials=[];last=0;previous={sales:0,group:0,direct:0,human:0,library:0};document.querySelector('[data-notification-toasts]')?.remove()}clearInterval(timer);timer=owner?setInterval(()=>{if(document.visibilityState==='visible')refresh()},30000):null;refresh(true)}
 function go(page,section=''){if(page==='loja'){try{localStorage.setItem('neo-shop-orders-seen:'+owner,new Date().toISOString())}catch{}window.NeoShop?.openManageOrders?.()}if(section==='library'){const latest=libraryLatest();if(latest)set('neo-library-seen',latest)}const button=document.createElement('button');button.hidden=true;button.dataset.go=page;if(section==='direct')button.dataset.supportShortcut='true';else if(section)button.dataset.communitySection=section;document.body.append(button);button.click();button.remove();shopBadge()}
 document.addEventListener('click',event=>{const close=event.target.closest('[data-notification-dismiss]');if(close){event.preventDefault();dismiss(close.closest('[data-notification-toast]').dataset.notificationToast);return}const action=event.target.closest('[data-notification-action]');if(!action)return;const kind=action.closest('[data-notification-toast]').dataset.notificationToast;dismiss(kind);if(kind==='sales')go('loja');else if(kind==='library')go('comunidade','library');else go('comunidade',kind==='group'?'feed':'direct')});
 document.addEventListener('neo:messages',event=>setTimeout(()=>notify(event.detail||{}),500));
 document.addEventListener('neo:library-seen',event=>{const latest=event.detail?.latest||libraryLatest();if(latest)set('neo-library-seen',latest);dismiss('library');previous.library=0});
 window.addEventListener('focus',()=>refresh(true));
 setInterval(()=>{const user=window.NeoCloud?.user,isAdmin=!!window.NeoCloud?.admin;if((user?.id||'')!==owner||isAdmin!==admin)session(user,isAdmin);else shopBadge()},1000);
 return {session,refresh,notify};
})();
